#!/usr/bin/env bash
# Fixes the actual cause of the reinstall failure just seen live on Ewan:
#
#     python/python.exe: Can't unlink already-existing object: Permission denied
#     Extracting Python runtime failed (exit code 1).
#
# install.ps1 already had a Stop-Service + WaitForStatus("Stopped", 30s)
# step specifically added for this (its own comment: "the old service is
# still running and holding its DLLs open") - but it was trusting the SCM's
# "Stopped" status, and the service was reporting that status too early.
#
# service_files/windows/opslab_agent_service.py's SvcDoRun()/main() started
# agent.main.run() on a background thread, waited on its OWN stop event
# (signaled instantly by SvcStop()), and returned immediately - WITHOUT
# ever waiting for that background thread to actually finish. Real cleanup
# (ProcessSupervisor.stop() terminating the supervised kiosk-app child,
# which holds the bundled Python runtime's DLLs open) runs asynchronously
# on that thread and could still be mid-flight when pywin32 reported the
# service STOPPED to the SCM - so install.ps1's WaitForStatus returned
# "stopped" while python.exe and its DLLs were, for a moment longer, still
# open.
#
# Fixed with a t.join(timeout=30) after the wait, so the service doesn't
# report itself stopped until agent.main.run()'s own shutdown has actually
# finished (or 30s have passed, matching install.ps1's own wait budget) -
# not just been signaled to start.
#
# Verified with a threading simulation of the exact race: reproduced the
# old behavior reporting "stopped" while cleanup was still 500ms from
# finishing, confirmed the fix waits for it correctly.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt service_files; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

echo "==> Extracting fixed agent/ + service_files/ into this repo"
TMP_EXTRACT="$(mktemp -d)"
base64 -d > "$TMP_EXTRACT/opslab-agent.tar.gz" << 'AGENT_TAR_EOF_MARKER'

AGENT_TAR_EOF_MARKER
tar -xzf "$TMP_EXTRACT/opslab-agent.tar.gz" -C "$TMP_EXTRACT"

if ! grep -q "t.join(timeout=30)" "$TMP_EXTRACT/service_files/windows/opslab_agent_service.py"; then
    echo "    ERROR: fix not found in the extracted payload!"
    rm -rf "$TMP_EXTRACT"
    exit 1
fi

rm -f agent/config.py.bak
cp -f "$TMP_EXTRACT/agent/"*.py agent/
cp -f "$TMP_EXTRACT/service_files/windows/opslab_agent_service.py" service_files/windows/opslab_agent_service.py
echo "    Updated agent/*.py and service_files/windows/opslab_agent_service.py in this repo."

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz (served by /install.ps1)"
cp -f "$TMP_EXTRACT/opslab-agent.tar.gz" app/static/installers/opslab-agent.tar.gz
rm -rf "$TMP_EXTRACT"

echo "==> Verifying"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    served agent tarball is readable"

echo ""
echo "Done. On Ewan, the Python runtime lock from the failed attempt was almost"
echo "certainly transient (the old process finishes exiting shortly after -"
echo "just later than Windows was told) - simply retry the SAME command again:"
echo "    irm https://kiosksys.opslabsystems.cloud/install.ps1 -OutFile install.ps1; .\\install.ps1 -Token <fresh-token> -AdminUrl https://kiosksys.opslabsystems.cloud"
echo ""
echo "If it hits the exact same 'Permission denied' error again, something is"
echo "still holding those files open - check for a lingering process first:"
echo "    Get-Process | Where-Object { \$_.Path -like \"C:\\Program Files\\OpsLabAgent*\" }"
echo "and stop any you find (Stop-Process -Id <pid> -Force) before retrying."
